/**
 * THE PAR PARITY TRIPWIRE (h4 Lane F2, engineering note §4 item (d) — the
 * bedroom-sandbox drift). `pars.json` is generated by
 * `scripts/gen-pars.mjs` from a headless replay of every reference build,
 * and `pars --check` now gates that file against re-computation in CI. But
 * the file is only HALF the claim: every level ALSO declares an inline
 * `Level.par`, used as the fallback and printed in the source comments —
 * and the two claims of ONE truth had never been compared. The
 * bedroom-sandbox row shipped `parTime: 3.15` for four programs while its
 * own level file said `measured 2.733` and the physics measured 2.733
 * (root cause: a `pars` regeneration run against a dirty tree mid-tune,
 * committed as a stale row; no spec ever scored a sandbox against pars,
 * so it rode silent).
 *
 * This tripwire compares them for every registered level, on the vitest
 * side of the gate (the CI `pars --check` step covers the replay side).
 * Two inline pars are declared PLACEHOLDERS by their own source and are
 * exempt with their reasons stated — the feel rig's `time: 5` is the
 * rig's promise, not a measurement, and the house's `time: 0` declares a
 * run VERDICTED IN ROOMS, not a par clock. If either ever stops being a
 * placeholder, deleting its exemption here is the whole act.
 */
import { describe, expect, test } from 'vitest';
import { readdirSync } from 'node:fs';
import { PARS } from '../../src/world/stars.ts';

const LEVELS_DIR = new URL('../../src/world/levels/', import.meta.url);
// every level module registers itself on import (the gen-pars convention)
for (const f of readdirSync(LEVELS_DIR).filter((f) => f.endsWith('.level.ts'))) {
  await import(new URL(f, LEVELS_DIR).href);
}
const { LEVELS } = await import('../../src/world/levels/feeltrack.level.ts');
const { HOUSE_ID } = await import('../../src/world/levels/house.level.ts');

/** The two declared placeholders — see the header. */
const PLACEHOLDER_IDS: readonly string[] = ['feeltrack', HOUSE_ID];

const ids = Object.keys(LEVELS as Record<string, { par?: { time: number; pieces?: number } }>).sort();

/** The generation law of `parTime` (gen-pars): measured seconds, ceil to
 *  the next 0.05. Level files state their claim either way — some raw
 *  measured (2.67), some already ceiled (2.75) — so the comparison that
 *  means something is ROW == CEIL(CLAIM): one application of the law
 *  onto any convention, and drift of ANY size (the 3.15-vs-2.75 kind)
 *  still lands red. */
const ceil05 = (s: number): number => Math.ceil(s * 20 - 1e-9) / 20;

describe('pars.json ↔ inline Level.par parity (the (d) tripwire)', () => {
  test('every registered level has a pars.json row', () => {
    for (const id of ids) expect(PARS[id], `row for ${id}`).toBeDefined();
  });

  test('every pars row belongs to a registered level (no orphan rows)', () => {
    for (const id of Object.keys(PARS)) expect(LEVELS[id], `level for row ${id}`).toBeDefined();
  });

  test('the pars TIME row is the 0.05-ceil of the inline claim (rooms-verdict and rig promises excepted)', () => {
    for (const id of ids) {
      if (PLACEHOLDER_IDS.includes(id)) continue;
      const level = (LEVELS as Record<string, { par?: { time: number } }>)[id]!;
      expect(PARS[id]!.time, `parTime drift on ${id} — run \`npm run pars\``).toBe(ceil05(level.par!.time));
    }
  });

  test('the par PIECES line matches the inline claim where one is declared', () => {
    for (const id of ids) {
      const level = (LEVELS as Record<string, { par?: { pieces?: number } }>)[id]!;
      if (level.par?.pieces === undefined) continue;
      expect(PARS[id]!.pieces, `parPieces drift on ${id}`).toBe(level.par.pieces);
    }
  });

  test('the (d) regression itself: bedroom-sandbox row is the measured 2.75, not the stale 3.15', () => {
    // the disclosed lie, pinned — if a dirty-tree regeneration ever
    // re-ships it, THIS names it, not a sandbox star line three months
    // from now
    expect(PARS['bedroom-sandbox']!.time).toBe(2.75);
    expect((LEVELS as Record<string, { par: { time: number } }>)['bedroom-sandbox']!.par.time).toBe(2.75);
  });
});
